    static boolean isEligibleFreshSpawnReason(MobSpawnType spawnReason) {
        return spawnReason != MobSpawnType.SPAWN_EGG;
    }

    static boolean isEligiblePlayerState(boolean alive, boolean removed, boolean creative, boolean spectator, boolean invulnerable) {
        return alive && !removed && !spectator;
    }

